const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
let repos = [];
let github_ok = true;
let error = null;

try {
  const repoList = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/users/Philip8q/repos?type=owner&per_page=100',
    headers: { 'User-Agent': 'weekly-review-assistant', 'Accept': 'application/vnd.github+json' },
    json: true,
  });

  const publicRepos = (repoList || []).filter(r => !r.private);

  for (const repo of publicRepos) {
    try {
      const commits = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://api.github.com/repos/Philip8q/${repo.name}/commits?since=${since}&per_page=100`,
        headers: { 'User-Agent': 'weekly-review-assistant', 'Accept': 'application/vnd.github+json' },
        json: true,
      });
      repos.push({
        name: repo.name,
        commit_count: Array.isArray(commits) ? commits.length : 0,
        commits: (Array.isArray(commits) ? commits : []).map(c => ({
          sha: c.sha.slice(0, 7),
          message: c.commit.message.split('\n')[0],
          date: c.commit.author.date,
        })),
      });
    } catch (e) {
      repos.push({ name: repo.name, commit_count: 0, commits: [], repo_error: e.message });
    }
  }
} catch (e) {
  github_ok = false;
  error = e.message;
}

const total_commits = repos.reduce((sum, r) => sum + r.commit_count, 0);
return [{ json: { github_ok, error, since, repos, total_commits } }];
